/// A `\r` that ends what has arrived may still be the line end: a line of exactly 1 MiB whose `\r` and
/// `\n` arrive in separate reads is one piece. Fed item by item, so the read boundary is exact.
#[test]
fn a_1_mib_line_split_before_its_newline_is_one_piece() {
    let shared = Arc::new(Shared::new(true, [Stream::Stdout, Stream::Stderr], [true, false]));
    shared.claim(Claim::Attached).unwrap();
    let mut lines = Lines::new(Arc::clone(&shared));
    shared.accept(0, &vec![b'a'; MIB]);
    shared.accept(0, b"\r");
    assert!(pending(lines.next()), "a piece was cut before the line end arrived");
    shared.accept(0, b"\nEND\n");
    shared.finish(0, None);
    let got = bounded(&runtime(), drain(&mut lines));
    let got: Vec<_> = shape(&got).into_iter().map(|l| (l.1, l.3)).collect();
    assert_eq!(got, [(MIB, false), (3, false)]);

assert_eq!(
    pick(Stream::Stdout),
    [(2, None), (UNATTACHED - 4 + 3, None), (4, Some(4)), (4, None)]
);
assert_eq!(pick(Stream::Stderr), [(UNATTACHED, None), (0, Some(2))]);
assert!(got.iter().all(|l| !l.continues));

fn dropping_lines_counts_what_they_held() {
    let rt = runtime();
    let (pumps, shared) = bare(&rt);
    let mut lines = pumps.lines().unwrap();
    shared.accept(0, b"one\ntwo\r\npar");
    assert_eq!(bounded(&rt, lines.next()).unwrap().unwrap().text, "one");
    assert_eq!(pumps.dropped().stdout, 0);
    drop(lines);
    assert_eq!(pumps.dropped().stdout, 5 + 3);

/// Runs `f` to completion on `rt`; more than `LIMIT` fails the test.
fn bounded<F: Future>(rt: &Runtime, f: F) -> F::Output {
    rt.block_on(async { tokio::time::timeout(LIMIT, f).await.expect("timed out") })
}

fn pipe() -> (Pipe, PipeWriter) {
    let (read, write) = std::io::pipe().unwrap();
    (Pipe::from(read), write)
}

/// A pipe child: its pumps, and the writing ends of its stdout and stderr.
fn child(rt: &Runtime, text: bool) -> (Pumps, PipeWriter, PipeWriter) {
    let ((out, out_w), (err, err_w)) = (pipe(), pipe());
    let source = Source::Pipes {
        stdout: out,
        stderr: Some(err),
    };
    (Pumps::start(rt.handle(), source, text).unwrap(), out_w, err_w)
}

/// Pumps without reader threads: the test plays the readers (`accept`, `finish`), so the queue holds exactly
/// what it pushed.
fn bare(rt: &Runtime) -> (Pumps, Arc<Shared>) {
    let shared = Arc::new(Shared::new(true, [Stream::Stdout, Stream::Stderr], [true, true]));
    let pumps = Pumps {
        shared: Arc::clone(&shared),
        rt: rt.handle().clone(),
    };
    (pumps, shared)

/// Polls until `cond` holds (a reader thread got that far); more than `LIMIT` fails the test.
fn until(mut cond: impl FnMut() -> bool) {
    let start = Instant::now();
    while !cond() {
        assert!(start.elapsed() < LIMIT, "condition never held");
        thread::sleep(Duration::from_millis(1));
    }
}

/// Polls `fut` once, runs `then` (e.g. starts a writer once a claim was made), then awaits `fut`.
async fn after_first_poll<F: Future>(fut: F, then: impl FnOnce()) -> F::Output {
    let mut fut = pin!(fut);
    let mut then = Some(then);
    poll_fn(|cx| {
        let polled = fut.as_mut().poll(cx);
        if let Some(then) = then.take() {
            then();
        }
        polled
    })
    .await

