impl Drop for Child {
    fn drop(&mut self) {
        // A forked copy touches no lock and commands nothing; its fields just drop.
        if self.inner.life.at_home() {
            self.inner.life.kill();
            self.inner.close_ends();
        }

/// Starts a pipe child (`InvalidArgument` if `req.mode` is a terminal).
pub(crate) fn spawn_pipe(req: &Request, opts: &Options) -> Result<PipeChild, Error> {
    if let Mode::Pty(_) = req.mode {
        return Err(Error::pty_needs_spawn_pty());
    }
    let spec = spawn::prepare(req)?;
    deadline::refuse_if_cancelled(opts)?;
    let rt = client::runtime()?;
    let spawned = client::spawn(&spec)?;
    let child = Child::start(rt.handle(), spawned, opts.text, spec.grace)?;
    if opts.backpressure {
        child.inner.pumps.hold(); // before anyone can claim the output
    }
    deadline::arm(rt.handle(), &child.inner, req.timeout, opts.cancel.clone());
    memory::arm(rt.handle(), &child.inner, req.max_rss_bytes);
    Ok(PipeChild { child })
}

/// Starts a terminal child.
pub(crate) fn spawn_pty(req: &Request, opts: &Options) -> Result<PtyChild, Error> {
    let spec = spawn::prepare(req)?;
    deadline::refuse_if_cancelled(opts)?;
    let rt = client::runtime()?;
    let spawned = client::spawn(&spec)?;
    // `start` returns with the terminal's reader running (`io::Pumps::start`); only then may the held Unix root exec
    // (ADR-0005 R9), or a program that prints and exits at once can lose its output on macOS. An exec failure comes
    // back here; dropping `child` then ends the tree and lets the readers go.
    let child = Child::start(rt.handle(), spawned, opts.text, spec.grace)?;
    child.inner.life.go()?;
    deadline::arm(rt.handle(), &child.inner, req.timeout, opts.cancel.clone());
    memory::arm(rt.handle(), &child.inner, req.max_rss_bytes);
    Ok(PtyChild { child })

async fn enforce(mut deadline: Deadline, inner: Arc<Inner>) {
    let event = first(deadline.fired(), settled(&inner)).await;
    let (inner, cause) = match event {
        First::A(cause) => (inner, cause),
        First::B(Settled::Over) => return,
        First::B(Settled::Lingering) => {
            let child = Arc::downgrade(&inner);
            drop(inner);
            match linger(&mut deadline, &child).await {
                Some(fired) => fired,
                None => return,
            }
        }
    };
    // A failure here (the supervisor is gone) also reaches every waiter of the child (`wait`, `stop`) on its own.
    let _ = inner.stop_with(cause, inner.grace).await;
}

/// The lingering state: the child and the cause once the deadline fires, or `None` once the child was dropped,
/// nothing is left of its tree, or its supervisor cannot tell. It holds the child only while it checks: a dropped
/// child fails to upgrade, and a stopped tree lists nothing without a round trip. The deadline races each whole
/// check, so it wins over a pending `List` (the check is dropped, and the stop is sent at once).
async fn linger(deadline: &mut Deadline, child: &Weak<Inner>) -> Option<(Arc<Inner>, Reason)> {
    loop {
        match first(deadline.fired(), still_lingering(child)).await {
            First::A(cause) => return Some((child.upgrade()?, cause)),
            First::B(true) => {}
            First::B(false) => return None,
        }
    }
}

/// After `LINGER_CHECK`: whether the child still exists and its tree still has members.
async fn still_lingering(child: &Weak<Inner>) -> bool {
    tokio::time::sleep(LINGER_CHECK).await;
    let Some(inner) = child.upgrade() else {
        return false;
    };
    // `Err`: a lost supervisor (for good) or a broken inventory, which the client does not tell apart; through that
    // supervisor the deadline could stop nothing reliably either way.
    inner.life.processes().await.is_ok_and(|left| !left.is_empty())

/// Resolves once the output is over and the root exited.
async fn settled(inner: &Inner) -> Settled {
    inner.pumps.ended().await;
    match inner.life.wait().await {
        // The root's own end (or a library act after it): ask once whether anything is left to time (an `Err` ends
        // it, as in `linger`).
        Ok(exit) if matches!(exit.reason, Reason::Exit | Reason::Signal) => match inner.life.processes().await {
            Ok(left) if !left.is_empty() => Settled::Lingering,
            Ok(_) | Err(_) => Settled::Over,
        },
        _ => Settled::Over,

/// `Aborted` or `Timeout`, whichever fired first (a cancellation wins a tie).
pub(super) async fn fired(&mut self) -> Reason {
    let Deadline { alarm, cancel } = self;
    let aborted = async {
        match cancel {
            Some(token) => token.cancelled().await,
            None => pending().await,
        }
    };
    let expired = async {
        match alarm {
            Some(alarm) => alarm.await,
            None => pending().await,
        }
    };
    match first(aborted, expired).await {
        First::A(()) => Reason::Aborted,
        First::B(()) => Reason::Timeout,
    }

pub(super) fn of(root: RootExit, cause: Option<Reason>) -> Exit {
    let (code, signal, own) = match root {
        RootExit::Code(code) => (Some(code), None, Reason::Exit),
        RootExit::Signal(num) => (None, Some(signal_name(num, std::env::consts::OS)), Reason::Signal),
    };
    let reason = match cause {
        Some(acted @ (Reason::Killed | Reason::Timeout | Reason::Aborted | Reason::MemoryExceeded)) => acted,
        Some(Reason::Exit | Reason::Signal) | None => own,
    };
    Exit { code, signal, reason }

/// Commits `cause` unless one is committed already, then ends the whole tree with one deadline: graceful now,
/// forced at `grace` (whole milliseconds, see `grace`). Resolves with the root's `Exit` once the supervisor
/// confirmed the tree gone, at once if it is gone already. After the root exited, only its descendants are left to
/// stop, and the root's `Exit` is unchanged. Overlapping calls share the earliest deadline (the supervisor's rule).
/// In a forked copy, the client's refusal comes back before any lock is taken.
pub(super) async fn stop(&self, cause: Reason, grace: Duration) -> Result<Exit, Error> {
    if self.at_home() {
        self.commit(cause);
    }
    self.tree.stop(grace).await?;
    self.wait().await
}

/// Force-kills the tree without waiting for it (drop): never blocks. Does nothing in a forked copy.
pub(super) fn kill(&self) {
    if self.at_home() {
        self.commit(Reason::Killed);
        self.tree.stop_detached(Duration::ZERO);
    }
}

/// Contract §7: the cause is committed when the library acts, before the termination is sent.
fn commit(&self, cause: Reason) {
    let mut committed = lock(&self.cause);
    if let Cause::Open = *committed {
        *committed = if self.root_exited() {
            Cause::Root
        } else {
            Cause::Acted(cause)
        };
    }
}

/// Whether the client has already observed the root's exit, without waiting: `Tree::exited` is ready on its
/// first poll once the exit is known. Polled outside tokio's cooperative budget, which could otherwise make a
/// known exit look pending.
fn root_exited(&self) -> bool {
    let mut cx = Context::from_waker(Waker::noop());
    let exited = pin!(tokio::task::unconstrained(self.tree.exited()));
    matches!(exited.poll(&mut cx), Poll::Ready(Ok(_)))

/// A grace for `stop`: whole milliseconds, a fraction rounding up (contract §3); `InvalidArgument` above
/// 4294967295 ms.
pub(super) fn grace(grace: Duration) -> Result<Duration, Error> {
    let ms = grace.as_nanos().div_ceil(1_000_000);
    match u64::try_from(ms) {
        Ok(whole) if ms <= MAX_GRACE_MS => Ok(Duration::from_millis(whole)),
        _ => Err(Error::duration_out_of_range("graceMs", ms)),
    }

/// Holds the child only while it samples, so a dropped child (whose drop kills the tree) ends the watch. It ends
/// too once the tree lists nothing (stopped, or ended on its own) or the supervisor cannot list it.
async fn watch(child: Weak<Inner>, cap: u64) {
    loop {
        tokio::time::sleep(PERIOD).await;
        let Some(inner) = child.upgrade() else {
            return;
        };
        let Ok(members) = inner.life.processes().await else {
            return;
        };
        if members.is_empty() {
            return;
        }
        let pids: Vec<Pid> = members.iter().map(|m| Pid::from_u32(m.pid)).collect();
        // Reading the OS' tables is blocking work: off the runtime's workers.
        let Ok(rss) = tokio::task::spawn_blocking(move || resident(&pids)).await else {
            return;
        };
        if rss > cap {
            // Forced at once (no grace): a tree growing past its cap gets no time to grow further. A failure here
            // (the supervisor is gone) also reaches every waiter of the child on its own.
            let _ = inner.stop_with(Reason::MemoryExceeded, Duration::ZERO).await;
            return;
        }
    }

/// The resident bytes of `roots` and every descendant of theirs together; a process gone by now counts 0.
fn resident(roots: &[Pid]) -> u64 {
    let mut system = System::new();
    // Tasks off: on Linux each thread would be listed with its process' whole RSS.
    system.refresh_processes_specifics(
        ProcessesToUpdate::All,
        true,
        ProcessRefreshKind::nothing().without_tasks().with_memory(),
    );
    let processes = system.processes();
    let mut children: HashMap<Pid, Vec<Pid>> = HashMap::new();
    for process in processes.values() {
        if let Some(parent) = process.parent() {
            children.entry(parent).or_default().push(process.pid());
        }
    }
    let mut counted = HashSet::new();
    let mut pending = roots.to_vec();
    while let Some(pid) = pending.pop() {
        if counted.insert(pid) {
            pending.extend(children.get(&pid).into_iter().flatten().copied());
        }
    }
    counted
        .iter()
        .filter_map(|pid| processes.get(pid))
        .map(sysinfo::Process::memory)
        .sum()

/// Default `max_output_bytes` per stream (contract §6).
pub(crate) const DEFAULT_MAX_OUTPUT: usize = 16 << 20;

/// What `spawn::prepare` does not need (everything validated, incl. `timeout`, is in `spawn::Request`).
#[derive(Debug, Clone)]
pub(crate) struct Options {
    pub cancel: Option<CancellationToken>,
    pub text: bool,
    pub input: Option<Vec<u8>>,
    pub max_output_bytes: usize,
    /// `spawn()` with pipes only (WP-H): an attached consumer that falls behind holds the child back instead of
    /// losing output.
    pub backpressure: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            cancel: None,
            text: true,
            input: None,
            max_output_bytes: DEFAULT_MAX_OUTPUT,
            backpressure: false,
        }
